import re
scope='/tmp/EB21/525/scope_2.txt'
paths=[p.strip() for p in open(scope,encoding='utf-8',errors='ignore') if p.strip()]
pat_doc=re.compile(r'(?i)(received|earned)[^\n]{0,80}?(doctorate|ph\.d\.|phd)[^\n]{0,80}?(?:in|from)\s*(\d{4})')
pat_death=re.compile(r'(?i)(died|passed away)[^\n]{0,80}?(?:on\s+|in\s+)?(\d{4})')
pat_co=re.compile(r'(?i)co-?edit(?:ed|or)|edited by')
for p in paths:
    try: txt=open(p,encoding='utf-8',errors='ignore').read()
    except: continue
    docs=[int(m.group(3)) for m in pat_doc.finditer(txt)]
    deads=[int(m.group(2)) for m in pat_death.finditer(txt)]
    if not docs or not deads: continue
    if any(dy-doc==45 for doc in docs for dy in deads):
        if pat_co.search(txt):
            print('\nFILE',p)
            for line in txt.splitlines():
                if pat_co.search(line) or pat_doc.search(line) or pat_death.search(line):
                    print(line[:500])
