import re, collections, itertools
scope='/tmp/EB21/525/scope_1.txt'
paths=[p.strip() for p in open(scope,encoding='utf-8',errors='ignore') if p.strip()]
# extract candidate books 2008-2012 with co-editors and names
cand=[]
for p in paths:
    try:
        for i,line in enumerate(open(p,encoding='utf-8',errors='ignore'),1):
            if re.search(r'20(08|09|10|11|12)', line) and re.search(r'co-?edit(?:ed|or)|edited by', line, re.I):
                cand.append((p,i,line.strip()))
    except: pass
print('cand',len(cand))
# crude name extraction after patterns
name_to_lines=collections.defaultdict(list)
for p,i,l in cand:
    # grab names after 'with', 'co-editors:' etc
    for m in re.finditer(r'(?:with|co-editors?:|edited by)\s+([^\.;]+)', l, re.I):
        seg=m.group(1)
        # split on and / commas
        parts=re.split(r',| and | & |;|\)|\(', seg)
        for part in parts:
            part=part.strip(' .')
            if len(part.split())>=2 and any(w[:1].isupper() for w in part.split()):
                name_to_lines[part].append((p,i,l))
# show names with few lines
for name,lines in list(name_to_lines.items())[:200]:
    print('NAME',name,'COUNT',len(lines))
    for p,i,l in lines[:2]:
        print(' ',p,i,l[:180])
